#!/usr/bin/env node
/**
 * Compiles the Markdown Help Center and legal documents in /content into typed
 * TypeScript modules under /shared/content. Both the Angular app (prerendered pages)
 * and the API (support-bot grounding) import these modules.
 *
 * Usage: node scripts/build-content.mjs [--check]
 *   --check  fails when the generated files are out of date (used in CI)
 */
import { readdirSync, readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import { join, basename } from 'node:path';
import { Marked } from 'marked';

const root = process.cwd();
const check = process.argv.includes('--check');

function parseFrontmatter(raw, file) {
  const match = /^---\r?\n([\s\S]*?)\r?\n---\r?\n([\s\S]*)$/.exec(raw);
  if (!match) throw new Error(`Missing frontmatter in ${file}`);
  const data = {};
  for (const line of match[1].split(/\r?\n/)) {
    const m = /^([a-zA-Z]+):\s*(.*)$/.exec(line);
    if (!m) continue;
    let value = m[2].trim();
    if (value.startsWith('[') && value.endsWith(']')) {
      value = value
        .slice(1, -1)
        .split(',')
        .map((v) => v.trim().replace(/^["']|["']$/g, ''))
        .filter(Boolean);
    } else {
      value = value.replace(/^["']|["']$/g, '');
      if (/^\d+$/.test(value)) value = Number(value);
    }
    data[m[1]] = value;
  }
  return { data, body: match[2].replace(/\r\n/g, '\n').trim() };
}

function slugify(text) {
  return text
    .toLowerCase()
    .replace(/<[^>]+>/g, '')
    .replace(/&[a-z]+;/g, '')
    .replace(/[^a-z0-9\s-]/g, '')
    .trim()
    .replace(/\s+/g, '-')
    .slice(0, 60);
}

function plain(md) {
  return md
    .replace(/```[\s\S]*?```/g, ' ')
    .replace(/!\[[^\]]*\]\([^)]*\)/g, ' ')
    .replace(/\[([^\]]+)\]\([^)]*\)/g, '$1')
    .replace(/[*_`>#|]/g, '')
    .replace(/^\s*[-+]\s+/gm, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function render(body) {
  const toc = [];
  const marked = new Marked({ gfm: true });
  marked.use({
    renderer: {
      heading({ tokens, depth }) {
        const text = this.parser.parseInline(tokens);
        const id = slugify(text);
        if (depth === 2) toc.push({ id, title: text.replace(/<[^>]+>/g, '') });
        return `<h${depth} id="${id}">${text}</h${depth}>\n`;
      },
      link({ href, title, tokens }) {
        const text = this.parser.parseInline(tokens);
        const external = /^https?:\/\//.test(href);
        const t = title ? ` title="${title}"` : '';
        return external
          ? `<a href="${href}"${t} target="_blank" rel="noopener noreferrer">${text}</a>`
          : `<a href="${href}"${t}>${text}</a>`;
      },
      html() {
        return ''; // raw HTML is never allowed in content
      },
    },
  });
  const html = marked.parse(body);
  return { html, toc };
}

function sectionsOf(body) {
  const sections = [];
  const parts = body.split(/^##\s+/m);
  const intro = parts.shift();
  if (intro && plain(intro)) sections.push({ heading: 'Overview', text: plain(intro) });
  for (const part of parts) {
    const [heading, ...rest] = part.split('\n');
    const text = plain(rest.join('\n'));
    if (text) sections.push({ heading: heading.trim(), text });
  }
  return sections;
}

function load(dir) {
  const full = join(root, 'content', dir);
  if (!existsSync(full)) return [];
  return readdirSync(full)
    .filter((f) => f.endsWith('.md'))
    .sort()
    .map((f) => {
      const { data, body } = parseFrontmatter(readFileSync(join(full, f), 'utf8'), f);
      return { slug: basename(f, '.md'), data, body };
    });
}

const help = load('help')
  .map(({ slug, data, body }) => {
    const { html, toc } = render(body);
    return {
      slug,
      title: data.title,
      summary: data.summary ?? '',
      category: data.category ?? 'General',
      order: data.order ?? 99,
      keywords: data.keywords ?? [],
      actions: data.actions ?? [],
      updated: data.updated ?? '',
      html,
      toc,
      sections: sectionsOf(body),
    };
  })
  .sort((a, b) => a.order - b.order || a.title.localeCompare(b.title));

const legal = load('legal')
  .map(({ slug, data, body }) => {
    const { html, toc } = render(body);
    return {
      slug,
      title: data.title,
      summary: data.summary ?? '',
      version: String(data.version ?? ''),
      updated: data.updated ?? '',
      order: data.order ?? 99,
      words: plain(body).split(' ').length,
      html,
      toc,
    };
  })
  .sort((a, b) => a.order - b.order);

const banner = '// AUTO-GENERATED by scripts/build-content.mjs from /content. Do not edit by hand.\n/* eslint-disable */\n';

const helpTs = `${banner}
export interface HelpSection { heading: string; text: string }
export interface HelpArticle {
  slug: string; title: string; summary: string; category: string; order: number;
  keywords: string[]; actions: string[]; updated: string; html: string;
  toc: { id: string; title: string }[]; sections: HelpSection[];
}
export const HELP_ARTICLES: HelpArticle[] = ${JSON.stringify(help, null, 1)};
`;

const legalTs = `${banner}
export interface LegalDoc {
  slug: string; title: string; summary: string; version: string; updated: string; order: number;
  words: number; html: string; toc: { id: string; title: string }[];
}
export const LEGAL_DOCS: LegalDoc[] = ${JSON.stringify(legal, null, 1)};
`;

const outDir = join(root, 'shared', 'content');
mkdirSync(outDir, { recursive: true });
const outputs = [
  [join(outDir, 'help.generated.ts'), helpTs],
  [join(outDir, 'legal.generated.ts'), legalTs],
];

let stale = false;
for (const [file, content] of outputs) {
  const current = existsSync(file) ? readFileSync(file, 'utf8').replace(/\r\n/g, '\n') : '';
  if (current !== content) {
    stale = true;
    if (!check) writeFileSync(file, content);
  }
}
if (check && stale) {
  console.error('Generated content is out of date. Run: npm run content');
  process.exit(1);
}
console.log(`content: ${help.length} help articles, ${legal.length} legal documents${check ? ' (check ok)' : ''}`);
